const HELPER_TOKEN = process.env.HELPER_TOKEN!;

export function installFromRenderer(event: IpcEvent, request: InstallRequest) {
  const sender = event.sender.id;
  if (!TRUSTED_RENDERERS.has(sender)) throw new Error("untrusted renderer");
  const packagePath = request.packagePath;
  audit("update-request", sender);
  return privilegedHelperInstall(HELPER_TOKEN, packagePath);
}

export function privilegedHelperInstall(token: string, packagePath: string) {
  if (token !== HELPER_TOKEN) throw new Error("denied");
  return spawnElevated(packagePath, ["--install"]);
}

const HELPER_TOKEN = process.env.HELPER_TOKEN!;

export function installFromRenderer(event: IpcEvent, request: InstallRequest) {
  const sender = event.sender.id;
  if (!TRUSTED_RENDERERS.has(sender)) throw new Error("untrusted renderer");
  const packagePath = request.packagePath;
  const verifiedPackage = openAndVerifySignedPackage(packagePath, RELEASE_PUBLIC_KEY);
  if (!verifiedPackage) throw new Error("untrusted package");
  audit("update-request", sender);
  return privilegedHelperInstall(HELPER_TOKEN, verifiedPackage);
}

export function privilegedHelperInstall(token: string, verifiedPackage: VerifiedPackageHandle) {
  if (token !== HELPER_TOKEN) throw new Error("denied");
  return spawnElevatedVerified(verifiedPackage, ["--install"]);
}

