package rewards

func Claim(store Store, user string, rewardID string) int {
    if store.Claimed(user, rewardID) {
        return store.Balance(user)
    }
    amount := store.RewardAmount(rewardID)
    balance := store.Balance(user) + amount
    store.SetBalance(user, balance)
    store.MarkClaimed(user, rewardID)
    return balance
}

package rewards

func Claim(store Store, user string, rewardID string) int {
    return store.SerializableTransaction(func(tx Tx) int {
        if !tx.InsertClaimIfAbsent(user, rewardID) {
            return tx.Balance(user)
        }
        amount := tx.RewardAmount(rewardID)
        balance := tx.Balance(user) + amount
        tx.SetBalance(user, balance)
        return balance
    })
}
